  'Mẫu': { en: 'Case', zh: '样例', ja: 'ケース', ko: '케이스', es: 'Caso', fr: 'Cas', de: 'Fall', th: 'กรณี', id: 'Kasus' },
  'Đang chấm': { en: 'Grading', zh: '评分中', ja: '採点中', ko: '채점 중', es: 'Calificando', fr: 'Notation…', de: 'Wird bewertet', th: 'กำลังให้คะแนน', id: 'Menilai' },
  'Đạt': { en: 'Passed', zh: '通过', ja: '合格', ko: '통과', es: 'Aprobado', fr: 'Réussi', de: 'Bestanden', th: 'ผ่าน', id: 'Lulus' },
