  // ---- Tài khoản & đăng nhập (app/accounts, app/login, components/user-menu) ----
  'Chủ sở hữu': { en: 'Owner', zh: '所有者', ja: 'オーナー', ko: '소유자', es: 'Propietario', fr: 'Propriétaire', de: 'Inhaber', th: 'เจ้าของ', id: 'Pemilik' },
  'Quản trị': { en: 'Admin', zh: '管理员', ja: '管理者', ko: '관리자', es: 'Administrador', fr: 'Administrateur', de: 'Administrator', th: 'ผู้ดูแล', id: 'Admin' },
  'Thành viên': { en: 'Member', zh: '成员', ja: 'メンバー', ko: '멤버', es: 'Miembro', fr: 'Membre', de: 'Mitglied', th: 'สมาชิก', id: 'Anggota' },
  'Chỉ xem': { en: 'Viewer', zh: '仅查看', ja: '閲覧者', ko: '뷰어', es: 'Lector', fr: 'Lecteur', de: 'Betrachter', th: 'ผู้ดู', id: 'Peninjau' },
  'Toàn quyền, kể cả quản lý tài khoản.': { en: 'Full access, including account management.', zh: '完全控制，包括管理账户。', ja: 'アカウント管理を含むフルアクセス。', ko: '계정 관리를 포함한 전체 권한.', es: 'Acceso total, incluida la gestión de cuentas.', fr: 'Accès complet, y compris la gestion des comptes.', de: 'Vollzugriff, einschließlich Kontoverwaltung.', th: 'สิทธิ์เต็ม รวมถึงการจัดการบัญชี', id: 'Akses penuh, termasuk mengelola akun.' },
  'Mọi thứ trừ tài khoản: kết nối AI, bí mật, cài đặt, phòng ban, ngân sách…': { en: 'Everything except accounts: AI connections, secrets, settings, departments, budgets…', zh: '除账户外的一切：AI 连接、密钥、设置、部门、预算…', ja: 'アカウント以外のすべて：AI 接続、シークレット、設定、部署、予算…', ko: '계정을 제외한 모든 것: AI 연결, 비밀, 설정, 부서, 예산…', es: 'Todo salvo las cuentas: conexiones de IA, secretos, ajustes, departamentos, presupuestos…', fr: 'Tout sauf les comptes : connexions IA, secrets, réglages, services, budgets…', de: 'Alles außer Konten: KI-Verbindungen, Geheimnisse, Einstellungen, Abteilungen, Budgets …', th: 'ทุกอย่างยกเว้นบัญชี: การเชื่อมต่อ AI ความลับ การตั้งค่า แผนก งบประมาณ…', id: 'Semuanya kecuali akun: koneksi AI, rahasia, pengaturan, departemen, anggaran…' },
  'Làm việc hằng ngày: chat, dự án, nhiệm vụ, phê duyệt, tài liệu, đánh giá. Không đổi cấu hình công ty.': { en: 'Day-to-day work: chat, projects, tasks, approvals, documents, evals. Can’t change company configuration.', zh: '日常工作：聊天、项目、任务、审批、文档、评测。不能更改公司配置。', ja: '日常業務：チャット、プロジェクト、タスク、承認、ドキュメント、評価。会社の設定は変更できません。', ko: '일상 업무: 채팅, 프로젝트, 작업, 승인, 문서, 평가. 회사 구성은 변경할 수 없습니다.', es: 'Trabajo diario: chat, proyectos, tareas, aprobaciones, documentos, evaluaciones. No puede cambiar la configuración de la empresa.', fr: 'Travail quotidien : chat, projets, tâches, approbations, documents, évaluations. Ne peut pas modifier la configuration de l’entreprise.', de: 'Tägliche Arbeit: Chat, Projekte, Aufgaben, Genehmigungen, Dokumente, Evaluierungen. Keine Änderung der Unternehmenskonfiguration.', th: 'งานประจำวัน: แชต โปรเจกต์ งาน การอนุมัติ เอกสาร การประเมิน เปลี่ยนการตั้งค่าบริษัทไม่ได้', id: 'Pekerjaan harian: obrolan, proyek, tugas, persetujuan, dokumen, evaluasi. Tidak dapat mengubah konfigurasi perusahaan.' },
  'Chỉ xem, không thay đổi được gì.': { en: 'View only, can’t change anything.', zh: '只能查看，无法做任何更改。', ja: '閲覧のみ。何も変更できません。', ko: '보기만 가능하며 아무것도 변경할 수 없습니다.', es: 'Solo ver, no puede cambiar nada.', fr: 'Consultation seule, aucune modification possible.', de: 'Nur ansehen, keine Änderungen möglich.', th: 'ดูได้อย่างเดียว เปลี่ยนแปลงอะไรไม่ได้', id: 'Hanya melihat, tidak bisa mengubah apa pun.' },
  'Mỗi người một tài khoản với vai trò riêng. Khi đã có tài khoản, mọi người phải đăng nhập mới vào được văn phòng.': { en: 'Everyone gets their own account with a role. Once accounts exist, people must sign in to enter the office.', zh: '每人一个账户，各有角色。创建账户后，所有人都必须登录才能进入办公室。', ja: '一人ひとりに役割付きのアカウントを用意します。アカウントを作成すると、オフィスに入るにはログインが必要になります。', ko: '사람마다 역할이 있는 계정을 하나씩 가집니다. 계정이 생기면 모두 로그인해야 사무실에 들어올 수 있습니다.', es: 'Cada persona tiene su cuenta con su propio rol. Cuando existan cuentas, todos deberán iniciar sesión para entrar en la oficina.', fr: 'Chacun a son compte avec son rôle. Dès qu’un compte existe, il faut se connecter pour entrer dans le bureau.', de: 'Jede Person erhält ein eigenes Konto mit Rolle. Sobald Konten existieren, muss man sich anmelden, um das Büro zu betreten.', th: 'แต่ละคนมีบัญชีพร้อมบทบาทของตัวเอง เมื่อมีบัญชีแล้ว ทุกคนต้องเข้าสู่ระบบจึงจะเข้าสำนักงานได้', id: 'Setiap orang punya akun dengan perannya sendiri. Setelah ada akun, semua orang harus masuk untuk memasuki kantor.' },
  'Thêm tài khoản': { en: 'Add account', zh: '添加账户', ja: 'アカウントを追加', ko: '계정 추가', es: 'Añadir cuenta', fr: 'Ajouter un compte', de: 'Konto hinzufügen', th: 'เพิ่มบัญชี', id: 'Tambah akun' },
  'Đã khoá': { en: 'Locked', zh: '已锁定', ja: 'ロック中', ko: '잠김', es: 'Bloqueada', fr: 'Verrouillé', de: 'Gesperrt', th: 'ล็อกแล้ว', id: 'Dikunci' },
